from __future__ import annotations

import json


def render_app(token: str) -> str:
    token_json = json.dumps(token)
    return r'''<!doctype html>
<html lang="vi">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>WP Clean Rebuild</title>
<style>
:root{--bg:#f4f7fb;--panel:#fff;--panel2:#f8fafc;--text:#142033;--muted:#728096;--line:#e7ecf3;--brand:#1268f3;--brand2:#0d55d4;--green:#15a46d;--yellow:#d78b0b;--red:#dc3f4d;--nav:#0d1830;--shadow:0 16px 50px rgba(28,45,76,.09);--radius:18px}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Inter,"Segoe UI",Roboto,Arial,sans-serif;background:var(--bg);color:var(--text)}button,input,select{font:inherit}button{cursor:pointer}a{color:inherit}
.shell{display:grid;grid-template-columns:248px 1fr;min-height:100vh}.sidebar{background:linear-gradient(180deg,#0a1530,#101f3f);color:#dfe8fa;padding:22px 18px;position:sticky;top:0;height:100vh}.brand{display:flex;align-items:center;gap:12px;padding:4px 8px 26px}.brandmark{width:42px;height:42px;border-radius:13px;background:linear-gradient(135deg,#2c7cff,#5aa4ff);display:grid;place-items:center;box-shadow:0 10px 24px rgba(20,104,243,.3)}.brandmark svg{width:23px;height:23px}.brand strong{display:block;color:#fff;font-size:15px;letter-spacing:.2px}.brand span{font-size:11px;color:#8fa4c9}.nav{display:grid;gap:7px}.navbtn{border:0;background:transparent;color:#91a6ca;text-align:left;padding:11px 13px;border-radius:11px;display:flex;gap:10px;align-items:center}.navbtn.active,.navbtn:hover{background:rgba(255,255,255,.09);color:#fff}.navico{width:20px;text-align:center}.sidefoot{position:absolute;left:18px;right:18px;bottom:20px;padding:13px;border:1px solid rgba(255,255,255,.09);border-radius:13px;color:#91a6ca;font-size:12px;line-height:1.5}.online{display:inline-block;width:8px;height:8px;border-radius:50%;background:#2fd393;margin-right:6px;box-shadow:0 0 0 4px rgba(47,211,147,.12)}
.main{min-width:0}.topbar{height:76px;background:rgba(255,255,255,.86);backdrop-filter:blur(14px);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 32px;position:sticky;top:0;z-index:15}.crumb{font-size:13px;color:var(--muted)}.crumb b{color:var(--text)}.top-actions{display:flex;gap:10px}.btn{border:0;border-radius:11px;padding:10px 15px;font-weight:650;transition:.16s ease;display:inline-flex;align-items:center;justify-content:center;gap:8px}.btn:hover{transform:translateY(-1px)}.btn-primary{background:var(--brand);color:white;box-shadow:0 8px 20px rgba(18,104,243,.2)}.btn-primary:hover{background:var(--brand2)}.btn-soft{background:#edf4ff;color:var(--brand)}.btn-light{background:#fff;border:1px solid var(--line);color:var(--text)}.btn-danger{background:#fff0f1;color:var(--red)}.btn-success{background:#eaf9f3;color:#0b8d5d}.btn-warning{background:#fff6e8;color:#ad6b00}.btn:disabled{opacity:.5;cursor:not-allowed;transform:none}.content{padding:30px 32px 50px;max-width:1500px;margin:auto}.hero{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:24px}.hero h1{margin:0;font-size:28px;letter-spacing:-.7px}.hero p{margin:8px 0 0;color:var(--muted);font-size:14px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:22px}.stat{background:var(--panel);border:1px solid var(--line);border-radius:15px;padding:18px 19px;box-shadow:0 5px 22px rgba(28,45,76,.035)}.stat .k{font-size:12px;color:var(--muted);font-weight:650}.stat .v{font-size:25px;font-weight:760;margin-top:7px}.stat .s{font-size:11px;color:var(--muted);margin-top:3px}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:22px 0 14px}.toolbar h2{font-size:17px;margin:0}.search{background:white;border:1px solid var(--line);border-radius:10px;padding:9px 12px;min-width:260px;outline:0}.search:focus{border-color:#b9d0f7;box-shadow:0 0 0 3px #e9f2ff}.projects{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.project{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:18px;box-shadow:0 7px 28px rgba(28,45,76,.045);transition:.18s ease;cursor:pointer}.project:hover{transform:translateY(-2px);box-shadow:var(--shadow);border-color:#d8e3f2}.project-head{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.project-icon{width:43px;height:43px;border-radius:13px;background:#edf4ff;color:var(--brand);display:grid;place-items:center;font-weight:800}.project-title{display:flex;gap:11px;min-width:0}.project-title h3{margin:2px 0 4px;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.project-title p{margin:0;color:var(--muted);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.badge{display:inline-flex;align-items:center;border-radius:999px;padding:5px 8px;font-size:10px;font-weight:750;white-space:nowrap}.badge-green{background:#e9f9f2;color:#0b8d5d}.badge-blue{background:#edf4ff;color:#1268f3}.badge-yellow{background:#fff6e5;color:#b36d00}.badge-red{background:#fff0f1;color:#c93140}.progressline{height:7px;background:#eef2f7;border-radius:99px;overflow:hidden;margin:17px 0 9px}.progressline>span{height:100%;background:linear-gradient(90deg,#1268f3,#5a9cff);display:block;border-radius:99px}.project-foot{display:flex;justify-content:space-between;color:var(--muted);font-size:11px}.empty{grid-column:1/-1;background:white;border:1px dashed #cdd8e6;border-radius:18px;padding:48px;text-align:center;color:var(--muted)}
.overlay{position:fixed;inset:0;background:rgba(8,18,36,.42);backdrop-filter:blur(4px);z-index:50;display:none}.overlay.show{display:block}.drawer{position:fixed;right:0;top:0;bottom:0;width:min(720px,94vw);background:#fff;z-index:60;transform:translateX(105%);transition:.25s ease;box-shadow:-20px 0 70px rgba(5,17,41,.18);overflow:auto}.drawer.show{transform:none}.drawer-head{padding:24px 26px 20px;border-bottom:1px solid var(--line);position:sticky;top:0;background:rgba(255,255,255,.94);backdrop-filter:blur(12px);z-index:3}.drawer-title{display:flex;justify-content:space-between;gap:12px}.drawer-title h2{margin:0;font-size:21px}.drawer-title p{margin:5px 0 0;font-size:12px;color:var(--muted)}.xbtn{border:0;background:#f2f5f9;width:34px;height:34px;border-radius:9px;color:#66768d;font-size:20px}.drawer-body{padding:22px 26px 40px}.section{margin-bottom:20px}.section-title{font-size:12px;text-transform:uppercase;letter-spacing:.7px;color:#8592a5;font-weight:800;margin-bottom:10px}.info-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.info{background:var(--panel2);border:1px solid var(--line);padding:12px 13px;border-radius:11px}.info span{display:block;color:var(--muted);font-size:10px;margin-bottom:4px}.info b{font-size:12px;word-break:break-all}.steps{display:grid;gap:7px}.step{display:grid;grid-template-columns:26px 1fr auto;align-items:center;gap:9px;padding:10px 11px;border:1px solid var(--line);border-radius:11px}.stepdot{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;background:#eef2f6;color:#92a0b2;font-size:11px;font-weight:800}.step.done .stepdot{background:#e6f8f0;color:#0d9462}.step.active{border-color:#bad2fb;background:#f5f9ff}.step.active .stepdot{background:#1268f3;color:#fff}.step label{font-size:12px;font-weight:650}.step small{font-size:10px;color:var(--muted)}.action-card{border:1px solid #dbe6f5;background:linear-gradient(180deg,#fbfdff,#f5f9ff);border-radius:16px;padding:17px;margin-top:15px}.action-card.danger{background:linear-gradient(180deg,#fffafa,#fff3f4);border-color:#ffd2d7}.action-card.warn{background:linear-gradient(180deg,#fffdf8,#fff8ec);border-color:#f7dfae}.action-card h3{margin:0 0 6px;font-size:15px}.action-card p{margin:0 0 12px;color:#64748a;font-size:12px;line-height:1.55}.actions{display:flex;gap:8px;flex-wrap:wrap}.confirm-input{width:100%;border:1px solid #efb8bf;border-radius:10px;padding:10px 11px;margin:2px 0 10px;outline:0}.checks{display:grid;gap:7px;margin:9px 0 13px}.check{display:flex;gap:9px;align-items:flex-start;background:#fff;border:1px solid var(--line);padding:10px;border-radius:10px}.check input{margin-top:2px}.check b{display:block;font-size:12px}.check span{font-size:10px;color:var(--muted)}.job{background:#101b31;color:#eaf2ff;border-radius:16px;padding:17px;margin-top:14px}.jobtop{display:flex;justify-content:space-between;gap:12px}.job h3{font-size:13px;margin:0}.job p{font-size:11px;color:#a9bbd7;margin:5px 0}.jobbar{height:7px;border-radius:99px;background:#25344e;overflow:hidden;margin:11px 0}.jobbar span{display:block;height:100%;background:linear-gradient(90deg,#3c86ff,#70b0ff);transition:.3s}.jobcur{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#8398bb;font-size:10px}.errorbox{margin-top:10px;border-radius:10px;padding:10px;background:#3a1b28;color:#ffc5cc;font-size:11px;white-space:pre-wrap}.logs{margin-top:10px;max-height:130px;overflow:auto;border-top:1px solid #263750;padding-top:8px}.logs div{font:10px/1.55 Consolas,monospace;color:#91a5c4}.foot-danger{border-top:1px solid var(--line);margin-top:26px;padding-top:18px;display:flex;justify-content:space-between;align-items:center;gap:12px}.foot-danger p{font-size:10px;color:var(--muted);margin:0}
.modal{position:fixed;inset:0;z-index:80;display:none;align-items:center;justify-content:center;padding:20px}.modal.show{display:flex}.modalbox{width:min(650px,96vw);max-height:92vh;overflow:auto;background:white;border-radius:20px;box-shadow:0 28px 90px rgba(8,18,36,.28);padding:24px}.modalhead{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.modalhead h2{margin:0;font-size:20px}.modalhead p{margin:5px 0 0;color:var(--muted);font-size:12px}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.field{display:grid;gap:6px}.field.full{grid-column:1/-1}.field label{font-size:11px;font-weight:750;color:#526177}.field input,.field select{border:1px solid var(--line);border-radius:10px;padding:10px 11px;outline:0;background:white}.field input:focus,.field select:focus{border-color:#9fc1f7;box-shadow:0 0 0 3px #eaf2ff}.modalactions{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}.toast{position:fixed;right:24px;bottom:24px;background:#142033;color:#fff;border-radius:12px;padding:12px 15px;z-index:120;box-shadow:0 15px 45px rgba(0,0,0,.2);font-size:12px;transform:translateY(120px);opacity:0;transition:.25s}.toast.show{transform:none;opacity:1}.toast.err{background:#a72d39}
@media(max-width:1100px){.projects{grid-template-columns:repeat(2,1fr)}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.shell{grid-template-columns:1fr}.sidebar{display:none}.topbar{padding:0 18px}.content{padding:22px 17px}.projects{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.hero{align-items:flex-start;flex-direction:column}.search{min-width:0;width:100%}.toolbar{align-items:stretch;flex-direction:column}.formgrid{grid-template-columns:1fr}.field.full{grid-column:auto}.info-grid{grid-template-columns:1fr}}
</style>
</head>
<body>
<div class="shell">
<aside class="sidebar">
  <div class="brand"><div class="brandmark"><svg viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2"><path d="M12 3 4.5 6v5.5c0 4.6 3.1 7.8 7.5 9.5 4.4-1.7 7.5-4.9 7.5-9.5V6L12 3Z"/><path d="m8.5 12 2.2 2.2 4.8-5"/></svg></div><div><strong>WP Clean Rebuild</strong><span>Recovery Console</span></div></div>
  <div class="nav"><button class="navbtn active"><span class="navico">⌂</span>Tổng quan</button><button class="navbtn" onclick="openCreate()"><span class="navico">＋</span>Tạo dự án</button></div>
  <div class="sidefoot"><span class="online"></span>Local mode đang hoạt động<br>Không mở cổng ra mạng LAN.</div>
</aside>
<main class="main">
  <header class="topbar"><div class="crumb">WP Clean Rebuild / <b>Tổng quan</b></div><div class="top-actions"><button class="btn btn-light" onclick="refreshAll()">↻ Làm mới</button><button class="btn btn-primary" onclick="openCreate()">＋ Tạo dự án</button></div></header>
  <div class="content">
    <div class="hero"><div><h1>Quản lý xử lý WordPress</h1><p>Chọn dự án, xem trạng thái và tiếp tục đúng bước đang dở.</p></div></div>
    <div class="stats" id="stats"></div>
    <div class="toolbar"><h2>Dự án</h2><input id="search" class="search" placeholder="Tìm domain hoặc tên dự án..." oninput="renderProjects()"></div>
    <div id="projects" class="projects"></div>
  </div>
</main>
</div>
<div id="overlay" class="overlay" onclick="closePanels()"></div>
<aside id="drawer" class="drawer"><div id="drawerContent"></div></aside>
<div id="createModal" class="modal"><div class="modalbox"><div class="modalhead"><div><h2>Tạo dự án mới</h2><p>Nhập thông tin hosting. Hệ thống sẽ tự sinh file cấu hình JSON.</p></div><button class="xbtn" onclick="closeCreate()">×</button></div>
<form id="createForm" onsubmit="submitCreate(event)"><div class="formgrid">
<div class="field"><label>Tên dự án</label><input id="f_name" name="name" placeholder="noi-that-dai-duong"></div>
<div class="field"><label>Domain / FTP Host *</label><input id="f_host" name="host" required placeholder="example.com" oninput="syncDefaults()"></div>
<div class="field"><label>Tài khoản FTP *</label><input name="username" required autocomplete="username"></div>
<div class="field"><label>Mật khẩu FTP *</label><input name="password" type="password" required autocomplete="current-password"></div>
<div class="field"><label>Giao thức</label><select name="protocol"><option value="ftp">FTP</option><option value="ftps">FTPS</option></select></div>
<div class="field"><label>Port</label><input name="port" type="number" value="21"></div>
<div class="field full"><label>Remote WordPress path</label><input id="f_remote" name="remotePath" placeholder="/domains/example.com/public_html"></div>
<div class="field full"><label>URL website</label><input id="f_url" name="siteUrl" placeholder="https://example.com"></div>
<div class="field"><label>Workers</label><input name="workers" type="number" min="1" max="16" value="4"></div>
<div class="field"><label>Block MiB</label><input name="blockMb" type="number" min="1" max="8" value="1"></div>
</div><div class="modalactions"><button type="button" class="btn btn-light" onclick="closeCreate()">Hủy</button><button class="btn btn-primary" type="submit">Tạo dự án</button></div></form></div></div>
<div id="toast" class="toast"></div>
<script>
const TOKEN=''' + token_json + r''';
let state={projects:[],selected:null};
const qs=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,opt={}){const o={...opt,headers:{'Content-Type':'application/json','X-WPClean-Token':TOKEN,...(opt.headers||{})}};const r=await fetch(url,o);let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||('HTTP '+r.status));return d}
function toast(msg,err=false){const el=qs('#toast');el.textContent=msg;el.className='toast show'+(err?' err':'');clearTimeout(window._tt);window._tt=setTimeout(()=>el.className='toast',3200)}
function progressOf(p){if(!p.steps?.length)return 0;return Math.round(p.steps.filter(x=>x.done).length/p.steps.length*100)}
function badge(p){const j=p.job;if(j?.status==='running')return '<span class="badge badge-blue">ĐANG CHẠY</span>';if(j?.status==='error')return '<span class="badge badge-red">LỖI</span>';if(j?.status==='needs-action')return '<span class="badge badge-yellow">CẦN XÁC NHẬN</span>';if(p.completed)return '<span class="badge badge-green">HOÀN TẤT</span>';return '<span class="badge badge-blue">ĐANG XỬ LÝ</span>'}
function renderStats(){const a=state.projects,total=a.length,done=a.filter(x=>x.completed).length,running=a.filter(x=>x.job?.status==='running').length,attention=a.filter(x=>['error','needs-action','paused'].includes(x.job?.status)).length;qs('#stats').innerHTML=`<div class="stat"><div class="k">TỔNG DỰ ÁN</div><div class="v">${total}</div><div class="s">Đang lưu trên máy này</div></div><div class="stat"><div class="k">ĐÃ HOÀN TẤT</div><div class="v">${done}</div><div class="s">Sẵn sàng bàn giao / dọn local</div></div><div class="stat"><div class="k">ĐANG CHẠY</div><div class="v">${running}</div><div class="s">Một job tại một thời điểm</div></div><div class="stat"><div class="k">CẦN XỬ LÝ</div><div class="v">${attention}</div><div class="s">Đang chờ xác nhận hoặc kỹ thuật</div></div>`}
function renderProjects(){const q=(qs('#search')?.value||'').toLowerCase(),list=state.projects.filter(p=>(p.name+' '+p.host).toLowerCase().includes(q));qs('#projects').innerHTML=list.length?list.map(p=>{const pc=progressOf(p);return `<article class="project" onclick="openProject('${encodeURIComponent(p.name)}')"><div class="project-head"><div class="project-title"><div class="project-icon">W</div><div><h3>${esc(p.name)}</h3><p>${esc(p.host)}</p></div></div>${badge(p)}</div><div class="progressline"><span style="width:${pc}%"></span></div><div class="project-foot"><span>${esc(p.nextLabel||'')}</span><b>${pc}%</b></div></article>`}).join(''):'<div class="empty"><b>Chưa có dự án</b><br><br><button class="btn btn-primary" onclick="openCreate()">＋ Tạo dự án đầu tiên</button></div>'}
async function refreshAll(){try{const d=await api('/api/projects');state.projects=d.projects||[];renderStats();renderProjects();if(state.selected){const found=state.projects.find(x=>x.name===state.selected);if(found)renderDrawer(found)}}catch(e){toast(e.message,true)}}
function stepHtml(p){const active=p.nextStage;return (p.steps||[]).map((s,i)=>`<div class="step ${s.done?'done':''} ${!s.done&&s.key===active?'active':''}"><div class="stepdot">${s.done?'✓':i+1}</div><label>${esc(s.label)}</label><small>${s.done?'Hoàn tất':(!s.done&&s.key===active?'Tiếp theo':'Chưa chạy')}</small></div>`).join('')}
function jobHtml(p){const j=p.job;if(!j||j.status==='idle')return '';return `<div class="job"><div class="jobtop"><div><h3>${esc(j.title||j.stage)}</h3><p>${esc(j.message||'')}</p></div><span class="badge ${j.status==='error'?'badge-red':j.status==='needs-action'?'badge-yellow':'badge-blue'}">${esc(j.status.toUpperCase())}</span></div>${j.status==='running'?`<div class="jobbar"><span style="width:${j.percent||4}%"></span></div><div class="jobcur">${esc(j.current||'Đang xử lý...')}</div>`:''}${j.error?`<div class="errorbox">${esc(j.error)}</div>`:''}${j.logs?.length?`<div class="logs">${j.logs.slice(-8).map(x=>`<div>${esc(x)}</div>`).join('')}</div>`:''}</div>`}
function decisionHtml(p){const j=p.job,d=j?.decision;if(j?.status==='running')return '';if(!d){if(p.completed)return `<div class="action-card"><h3>✅ Dự án đã hoàn tất</h3><p>Website đã được nhân sự xác nhận. Bạn có thể mở website hoặc xóa dữ liệu local khi không còn cần backup.</p><div class="actions"><a class="btn btn-success" target="_blank" href="${esc(p.url)}">Mở website ↗</a><a class="btn btn-light" target="_blank" href="${esc(p.adminUrl)}">Mở wp-admin ↗</a></div></div>`;return `<div class="action-card"><h3>Tiếp tục workflow</h3><p>Bước tiếp theo: <b>${esc(p.nextLabel)}</b>. Các bước an toàn sẽ tự chạy liên tiếp đến khi cần bạn xác nhận.</p><div class="actions"><button class="btn btn-primary" onclick="advance('${esc(p.name)}',{})">▶ Tiếp tục</button><button class="btn btn-light" onclick="testFtp('${esc(p.name)}')">Kiểm tra FTP</button></div></div>`}
if(d.type==='rebuild')return `<div class="action-card danger"><h3>⚠ Xác nhận rebuild WordPress</h3><p>${esc(j.message)}<br><b>Remote:</b> ${esc(d.remotePath)}</p><input id="confirmRebuild" class="confirm-input" placeholder="Nhập ${esc(d.confirmText)} để xác nhận"><div class="actions"><button class="btn btn-danger" onclick="confirmRebuild('${esc(p.name)}','${esc(d.confirmText)}')">Xác nhận và rebuild</button></div></div>`;
if(d.type==='resume-db')return `<div class="action-card warn"><h3>Tiếp tục database an toàn</h3><p>${esc(j.message)}</p><button class="btn btn-warning" onclick="advance('${esc(p.name)}',{resumeDb:true})">Tiếp tục import DB-only</button></div>`;
if(d.type==='theme')return `<div class="action-card"><h3>Theme an toàn</h3><p>${esc(j.message)}</p><div class="checks"><label class="check"><input id="themeParent" type="checkbox" checked><div><b>Cài Flatsome sạch</b><span>Dùng themes/flatsome.zip tin cậy</span></div></label>${d.hasChild?`<label class="check"><input id="themeChild" type="checkbox" checked><div><b>Quét và cài theme con ${esc(d.childSlug)}</b><span>Chỉ upload khi scan PASS${d.repairPath?' · có working-copy kỹ thuật':''}</span></div></label>`:''}</div><button class="btn btn-primary" onclick="runTheme('${esc(p.name)}',${d.hasChild?'true':'false'})">Tiếp tục theme</button></div>`;
if(d.type==='theme-repair')return `<div class="action-card warn"><h3>🛠 Theme con cần sửa</h3><p>${esc(j.message)}<br><b>${esc(d.path)}</b></p><div class="actions"><button class="btn btn-warning" onclick="openRepair('${esc(p.name)}')">Mở thư mục sửa</button><button class="btn btn-primary" onclick="advance('${esc(p.name)}',{themeInstall:true,childInstall:true})">Quét lại & tiếp tục</button></div></div>`;
if(d.type==='manual-theme')return `<div class="action-card warn"><h3>Theme cần cài thủ công</h3><p>${esc(j.message)}<br>Theme: <b>${esc(d.theme)}</b></p><button class="btn btn-primary" onclick="advance('${esc(p.name)}',{manualThemeAck:true})">Tôi đã cài theme sạch</button></div>`;
if(d.type==='manual-plugins')return `<div class="action-card warn"><h3>${d.count} plugin cần cài thủ công</h3><p>Hãy lấy bản sạch từ nhà cung cấp. Không dùng lại plugin code trong backup website nhiễm.</p><div class="actions"><button class="btn btn-primary" onclick="advance('${esc(p.name)}',{manualPluginsAck:true,manualPluginsUploaded:true})">Tôi đã cài xong</button><button class="btn btn-light" onclick="advance('${esc(p.name)}',{manualPluginsAck:true,manualPluginsUploaded:false})">Xử lý sau</button></div></div>`;
if(d.type==='final'){const h=d.home||{},a=d.admin||{};return `<div class="action-card"><h3>Kiểm tra nhanh website</h3><p>Trang chủ: <b>${h.ok?'✅':'⚠'} HTTP ${h.status||'?'}</b><br>wp-admin: <b>${a.ok?'✅':'⚠'} HTTP ${a.status||'?'}</b><br><br>Hãy mở website, kiểm tra warning PHP, header/footer, ảnh và chức năng chính.</p><div class="actions"><a class="btn btn-light" target="_blank" href="${esc(d.url)}">Mở frontend ↗</a><a class="btn btn-light" target="_blank" href="${esc(d.adminUrl)}">Mở wp-admin ↗</a><button class="btn btn-success" onclick="advance('${esc(p.name)}',{finalChoice:'complete'})">✅ Website ổn, hoàn tất</button><button class="btn btn-warning" onclick="advance('${esc(p.name)}',{finalChoice:'problem'})">Có lỗi, chờ kỹ thuật</button><button class="btn btn-light" onclick="advance('${esc(p.name)}',{finalChoice:'deep'})">Quét sâu</button></div></div>`}return ''}
function renderDrawer(p){state.selected=p.name;const pc=progressOf(p);qs('#drawerContent').innerHTML=`<div class="drawer-head"><div class="drawer-title"><div><h2>${esc(p.host)}</h2><p>${esc(p.name)} · ${esc(p.protocol)} · ${pc}% hoàn tất</p></div><button class="xbtn" onclick="closePanels()">×</button></div></div><div class="drawer-body"><div class="section"><div class="section-title">Thông tin dự án</div><div class="info-grid"><div class="info"><span>Website</span><b>${esc(p.url)}</b></div><div class="info"><span>Remote WordPress</span><b>${esc(p.remotePath)}</b></div><div class="info"><span>Workers</span><b>${esc(p.workers)}</b></div><div class="info"><span>Backup local</span><b>${esc(p.backupRoot)}</b></div></div></div><div class="section"><div class="section-title">Tiến độ</div><div class="steps">${stepHtml(p)}</div>${jobHtml(p)}${decisionHtml(p)}</div>${p.themeRepair?`<div class="section"><button class="btn btn-warning" onclick="openRepair('${esc(p.name)}')">🛠 Mở thư mục theme repair</button></div>`:''}<div class="foot-danger"><p>Xóa dự án chỉ xóa dữ liệu local, không đụng hosting.</p>${p.completed?`<button class="btn btn-danger" onclick="deleteProject('${esc(p.name)}')">Xóa dự án local</button>`:''}</div></div>`}
async function openProject(encoded){const name=decodeURIComponent(encoded);try{const p=await api('/api/projects/'+encodeURIComponent(name));state.selected=name;renderDrawer(p);qs('#overlay').classList.add('show');qs('#drawer').classList.add('show')}catch(e){toast(e.message,true)}}
function closePanels(){state.selected=null;qs('#overlay').classList.remove('show');qs('#drawer').classList.remove('show');closeCreate()}
function openCreate(){qs('#overlay').classList.add('show');qs('#createModal').classList.add('show')}
function closeCreate(){qs('#createModal').classList.remove('show');if(!qs('#drawer').classList.contains('show'))qs('#overlay').classList.remove('show')}
function syncDefaults(){const h=qs('#f_host').value.trim();if(!qs('#f_name').value)qs('#f_name').value=h.replace(/[^a-zA-Z0-9._-]+/g,'-').toLowerCase();qs('#f_remote').value=h?`/domains/${h}/public_html`:'';qs('#f_url').value=h?`https://${h}`:''}
async function submitCreate(e){e.preventDefault();const fd=new FormData(e.target),d=Object.fromEntries(fd.entries());d.port=Number(d.port||21);d.workers=Number(d.workers||4);d.blockMb=Number(d.blockMb||1);d.passive=true;try{const p=await api('/api/projects',{method:'POST',body:JSON.stringify(d)});closeCreate();e.target.reset();await refreshAll();toast('Đã tạo dự án '+p.name);openProject(encodeURIComponent(p.name))}catch(err){toast(err.message,true)}}
async function testFtp(name){try{toast('Đang kiểm tra FTP...');const d=await api('/api/projects/'+encodeURIComponent(name)+'/test',{method:'POST',body:'{}'});toast('FTP OK · '+d.remotePath)}catch(e){toast(e.message,true)}}
async function advance(name,opts){try{await api('/api/projects/'+encodeURIComponent(name)+'/advance',{method:'POST',body:JSON.stringify(opts||{})});toast('Đã bắt đầu xử lý');startPolling(name)}catch(e){toast(e.message,true)}}
function confirmRebuild(name,expected){const v=qs('#confirmRebuild')?.value.trim();if(v!==expected){toast('Hãy nhập đúng '+expected+' để xác nhận.',true);return}advance(name,{confirmRebuild:v})}
function runTheme(name,hasChild){advance(name,{themeInstall:!!qs('#themeParent')?.checked,childInstall:hasChild?!!qs('#themeChild')?.checked:false})}
async function openRepair(name){try{const d=await api('/api/projects/'+encodeURIComponent(name)+'/open-repair',{method:'POST',body:'{}'});toast('Đã mở '+d.path)}catch(e){toast(e.message,true)}}
async function deleteProject(name){const typed=prompt(`Xóa vĩnh viễn backup/report/config LOCAL của dự án?\nHosting không bị thay đổi.\n\nNhập chính xác: ${name}`,'');if(typed!==name)return;try{await api('/api/projects/'+encodeURIComponent(name)+'/delete',{method:'POST',body:JSON.stringify({confirmation:typed})});closePanels();await refreshAll();toast('Đã xóa dự án local '+name)}catch(e){toast(e.message,true)}}
let pollTimer=null;function startPolling(name){clearInterval(pollTimer);pollTimer=setInterval(async()=>{try{await refreshAll();if(state.selected===name){const p=await api('/api/projects/'+encodeURIComponent(name));renderDrawer(p);if(p.job && p.job.status!=='running'){clearInterval(pollTimer);pollTimer=null}}}catch{}},900)}
setInterval(()=>{if(!pollTimer)refreshAll()},6000);refreshAll();
</script>
</body></html>'''


__all__ = ["render_app"]
